.glow-b { width: 520px; height: 520px; background: rgba(16, 185, 129, 0.12); bottom: -200px; right: -140px; }

.shell { position: relative; z-index: 1; max-width: 1280px; margin: 0 auto; padding: 28px 20px 48px; }

.topbar { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; margin-bottom: 18px; flex-wrap: wrap; }
.title { margin: 0; font-size: 40px; letter-spacing: -0.03em; }
.subtitle { margin: 6px 0 0; color: var(--muted); font-size: 14.5px; }
