.panel { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; margin-bottom: 14px; backdrop-filter: blur(8px); }

.controls { display: grid; grid-template-columns: 1.2fr 2fr; gap: 18px; }
@media (max-width: 860px) { .controls { grid-template-columns: 1fr; } }

.lbl { display: block; font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); margin-bottom: 6px; font-weight: 700; }
