.drop-item { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; width: 100%; text-align: left; background: transparent; border: 0; color: var(--text); padding: 10px 12px; cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.06); }
.drop-item:hover { background: rgba(16,185,129,0.12); }
.drop-name { font-weight: 700; }
