.sum-row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 4px 0; }
.sum-count { font-weight: 800; color: #6ee7b7; }
.sum-in, .sum-city { color: var(--muted); font-size: 14px; }
.sum-city { font-weight: 700; color: var(--text); }
.badges { display: flex; gap: 8px; flex-wrap: wrap; }
.badge { background: var(--green-bg); border: 1px solid var(--green-border); color: #d1fae5; font-weight: 750; font-size: 13px; padding: 5px 12px; border-radius: 999px; font-variant-numeric: tabular-nums; }
