.base-list { display: flex; flex-direction: column; gap: 8px; }

/* Desktop grid */
.grid-desktop { overflow-x: auto; }
.d-row { display: grid; grid-template-columns: 190px repeat(24, minmax(36px, 1fr)) 32px; gap: 4px; align-items: stretch; }
.d-head { margin-bottom: 6px; }
.d-h { font-size: 11.5px; color: var(--muted); text-align: center; font-variant-numeric: tabular-nums; font-weight: 650; padding: 4px 0; }
.d-city-col { padding: 8px 10px 8px 4px; min-width: 0; }
.d-x-col { display: flex; align-items: center; justify-content: center; }
.city-name { background: none; border: 0; color: var(--text); font-weight: 750; font-size: 14.5px; cursor: pointer; padding: 0; text-align: left; }
.city-name:hover { color: #6ee7b7; text-decoration: underline; }
.ref { display: inline-block; font-size: 10px; font-weight: 800; letter-spacing: 0.08em; background: #fff; color: #0a0f1e; border-radius: 6px; padding: 2px 6px; margin-left: 8px; vertical-align: middle; }
.city-meta { font-size: 12px; color: var(--muted); margin-top: 3px; font-variant-numeric: tabular-nums; }
.x-btn { border: 1px solid var(--border); background: rgba(255,255,255,0.05); color: var(--muted); border-radius: 10px; cursor: pointer; font-size: 16px; line-height: 1; padding: 6px 9px; }
.x-btn:hover:not(:disabled) { color: #fca5a5; border-color: rgba(248,113,113,0.5); }
.x-btn:disabled { opacity: 0.3; cursor: not-allowed; }

.cell { text-align: center; font-size: 11px; font-variant-numeric: tabular-nums; padding: 10px 1px; border-radius: 9px; border: 1px solid transparent; white-space: nowrap; overflow: hidden; }
.cell.sleep { opacity: 0.32; background: rgba(255,255,255,0.03); color: var(--muted); }
.cell.awake { background: rgba(255,255,255,0.07); border-color: rgba(255,255,255,0.08); color: var(--text); }
.cell.overlap { background: var(--green-bg); border-color: var(--green-border); color: #ecfdf5; font-weight: 800; box-shadow: inset 0 0 0 1px rgba(16,185,129,0.35), 0 0 18px rgba(16,185,129,0.12); }

/* Mobile grid — separate layout */
.grid-mobile { display: none; }
@media (max-width: 767px) {
  .grid-desktop { display: none; }
  .grid-mobile { display: block; overflow-x: auto; }
  .title { font-size: 30px; }
}
@media (min-width: 768px) {
  .grid-mobile { display: none !important; }
}
.m-grid { display: grid; grid-template-columns: 64px repeat(var(--cols), minmax(96px, 1fr)); gap: 4px; min-width: 340px; }
.m-corner { font-size: 11px; color: var(--muted); font-weight: 700; padding: 8px 4px; }
.m-chead { padding: 6px 4px; }
.m-chead .x-btn { font-size: 11px; margin-top: 6px; padding: 5px 8px; }
.m-h { font-size: 11px; color: var(--muted); font-weight: 650; padding: 10px 0; text-align: center; font-variant-numeric: tabular-nums; }

.hint { text-align: center; color: var(--muted); font-size: 13.5px; padding: 14px 8px 0; }
.hint-sub { opacity: 0.8; }

