import './styles.css';

type Mode = 'meeting' | 'base';
type HourFormat = '12h' | '24h';

interface PersistedState {
  cityIds: string[];
  wake: number;
  sleep: number;
  format: HourFormat;
  mode: Mode;
}

const STORAGE_KEY = 'tz-overlap-checker-v1';
