success.beforeFullFileContent:
:root {
  --bg: #0a0f1e;
  --card: rgba(255, 255, 255, 0.045);
  --border: rgba(255, 255, 255, 0.1);
  --text: #eef2ff;
  --muted: #93a0bb;
  --green: #10b981;
  --green-bg: rgba(16, 185, 129, 0.22);
  --green-border: rgba(16, 185, 129, 0.55);
  --radius: 16px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Inter, Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

.page { position: relative; min-height: 100vh; overflow-x: clip; }
.glow { position: fixed; border-radius: 50%; filter: blur(120px); pointer-events: none; z-index: 0; }
.glow-a { width: 560px; height: 560px; background: rgba(59, 130, 246, 0.16); top: -180px; left: -140px; }
.glow-b { width: 520px; height: 520px; background: rgba(16, 185, 129, 0.12); bottom: -200px; right: -140px; }

.shell { position: relative; z-index: 1; max-width: 1280px; margin: 0 auto; padding: 28px 20px 48px; }

.topbar { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; margin-bottom: 18px; flex-wrap: wrap; }
.title { margin: 0; font-size: 40px; letter-spacing: -0.03em; }
.subtitle { margin: 6px 0 0; color: var(--muted); font-size: 14.5px; }
.subtitle strong { color: var(--text); }

.mode-switch { display: flex; background: rgba(255,255,255,0.06); border: 1px solid var(--border); border-radius: 999px; padding: 4px; }
.mode-btn { border: 0; background: transparent; color: var(--muted); font-weight: 650; font-size: 14px; padding: 9px 22px; border-radius: 999px; cursor: pointer; }
.mode-btn.active { background: #fff; color: #0a0f1e; }

.panel { background: var(--card); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; margin-bottom: 14px; backdrop-filter: blur(8px); }

.controls { display: grid; grid-template-columns: 1.2fr 2fr; gap: 18px; }
@media (max-width: 860px) { .controls { grid-template-columns: 1fr; } }

.lbl { display: block; font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); margin-bottom: 6px; font-weight: 700; }
.search { width: 100%; padding: 12px 14px; border-radius: 12px; border: 1px solid var(--border); background: rgba(0,0,0,0.3); color: var(--text); font-size: 14.5px; outline: none; }
.search:focus { border-color: rgba(16,185,129,0.6); box-shadow: 0 0 0 3px rgba(16,185,129,0.15); }
.add-wrap { position: relative; }
.dropdown { position: absolute; top: calc(100% + 8px); left: 0; right: 0; background: #111a30; border: 1px solid var(--border); border-radius: 12px; overflow: hidden; z-index: 20; box-shadow: 0 20px 60px rgba(0,0,0,0.5); max-height: 340px; overflow-y: auto; }
.drop-item { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; width: 100%; text-align: left; background: transparent; border: 0; color: var(--text); padding: 10px 12px; cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.06); }
.drop-item:hover { background: rgba(16,185,129,0.12); }
.drop-name { font-weight: 700; }
.drop-sub { font-size: 12px; color: var(--muted); }
.drop-empty { padding: 12px; color: var(--muted); font-size: 13.5px; }

.settings { display: flex; gap: 18px; align-items: flex-end; flex-wrap: wrap; }
.select { padding: 11px 12px; border-radius: 12px; border: 1px solid var(--border); background: rgba(0,0,0,0.3); color: var(--text); font-size: 14px; min-width: 110px; }
.mini-switch { display: flex; background: rgba(0,0,0,0.3); border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
.mini { border: 0; background: transparent; color: var(--muted); padding: 11px 18px; font-weight: 700; cursor: pointer; }
.mini.active { background: rgba(16,185,129,0.2); color: #a7f3d0; }
.awake-line { display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 13.5px; padding-bottom: 10px; }
.dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
.dot-awake { background: var(--green); box-shadow: 0 0 10px rgba(16,185,129,0.8); }
.dot-asleep { background: #475569; }

.summary { border-color: rgba(16,185,129,0.3); }
.sum-row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 4px 0; }
.sum-count { font-weight: 800; color: #6ee7b7; }
.sum-in, .sum-city { color: var(--muted); font-size: 14px; }
.sum-city { font-weight: 700; color: var(--text); }
.badges { display: flex; gap: 8px; flex-wrap: wrap; }
.badge { background: var(--green-bg); border: 1px solid var(--green-border); color: #d1fae5; font-weight: 750; font-size: 13px; padding: 5px 12px; border-radius: 999px; font-variant-numeric: tabular-nums; }
.warn { background: rgba(245,158,11,0.12); border: 1px solid rgba(245,158,11,0.4); color: #fcd34d; padding: 12px 14px; border-radius: 12px; font-weight: 650; }
.warn-inline { color: #fcd34d; font-size: 13.5px; font-weight: 600; }
.base-list { display: flex; flex-direction: column; gap: 8px; }

/* Desktop grid */
.grid-desktop { overflow-x: auto; }
.d-row { display: grid; grid-template-columns: 190px repeat(24, minmax(36px, 1fr)) 32px; gap: 4px; align-items: stretch; }
.d-head { margin-bottom: 6px; }
.d-h { font-size: 11.5px; color: var(--muted); text-align: center; font-variant-numeric: tabular-nums; font-weight: 650; padding: 4px 0; }
.d-city-col { padding: 8px 10px 8px 4px; min-width: 0; }
.d-x-col { display: flex; align-items: center; justify-content: center; }
.city-name { background: none; border: 0; color: var(--text); font-weight: 750; font-size: 14.5px; cursor: pointer; padding: 0; text-align: left; }
.city-name:hover { color: #6ee7b7; text-decoration: underline; }
.ref { display: inline-block; font-size: 10px; font-weight: 800; letter-spacing: 0.08em; background: #fff; color: #0a0f1e; border-radius: 6px; padding: 2px 6px; margin-left: 8px; vertical-align: middle; }
.city-meta { font-size: 12px; color: var(--muted); margin-top: 3px; font-variant-numeric: tabular-nums; }
.x-btn { border: 1px solid var(--border); background: rgba(255,255,255,0.05); color: var(--muted); border-radius: 10px; cursor: pointer; font-size: 16px; line-height: 1; padding: 6px 9px; }
.x-btn:hover:not(:disabled) { color: #fca5a5; border-color: rgba(248,113,113,0.5); }
.x-btn:disabled { opacity: 0.3; cursor: not-allowed; }

.cell { text-align: center; font-size: 11px; font-variant-numeric: tabular-nums; padding: 10px 1px; border-radius: 9px; border: 1px solid transparent; white-space: nowrap; overflow: hidden; }
.cell.sleep { opacity: 0.32; background: rgba(255,255,255,0.03); color: var(--muted); }
.cell.awake { background: rgba(255,255,255,0.07); border-color: rgba(255,255,255,0.08); color: var(--text); }
.cell.overlap { background: var(--green-bg); border-color: var(--green-border); color: #ecfdf5; font-weight: 800; box-shadow: inset 0 0 0 1px rgba(16,185,129,0.35), 0 0 18px rgba(16,185,129,0.12); }

/* Mobile grid — separate layout */
.grid-mobile { display: none; }
@media (max-width: 767px) {
  .grid-desktop { display: none; }
  .grid-mobile { display: block; overflow-x: auto; }
  .title { font-size: 30px; }
}
@media (min-width: 768px) {
  .grid-mobile { display: none !important; }
}
.m-grid { display: grid; grid-template-columns: 64px repeat(var(--cols), minmax(96px, 1fr)); gap: 4px; min-width: 340px; }
.m-corner { font-size: 11px; color: var(--muted); font-weight: 700; padding: 8px 4px; }
.m-chead { padding: 6px 4px; }
.m-chead .x-btn { font-size: 11px; margin-top: 6px; padding: 5px 8px; }
.m-h { font-size: 11px; color: var(--muted); font-weight: 650; padding: 10px 0; text-align: center; font-variant-numeric: tabular-nums; }

.hint { text-align: center; color: var(--muted); font-size: 13.5px; padding: 14px 8px 0; }
.hint-sub { opacity: 0.8; }

